              'Erik Solberg, 51, ist Senior Expedition Product Manager bei Hurtigruten Svalbard AS, der norwegischen Kreuzfahrtlinie mit 7 hybridbetriebenen Expeditionsschiffen in der Arktis. Hurtigrutens Gäste (Durchschnittsalter 58, Haushaltseinkommen über 350.000 $) zahlen 8.000-25.000 $ für 12-tägige Reisen. Gäste-Feedback 2023 zeigte „aktive Arktis-Erlebnisse“ als Nummer 1 der unerfüllten Wünsche – insbesondere das Paddeln in kleinen Gruppen zwischen Eisbergen und entlang von Gletscherfronten. Doch Standard-SUPs halten weder 2 °C Wassertemperatur und -5 °C Lufttemperatur aus noch die logistische Herausforderung des Einsatzes von Zodiacs im Eisbär-Gebiet. Erik hatte 2022 drei Marken getestet – alle versagten innerhalb von 5 Einsätzen (Ventile froren ein, Boards wurden spröde, und eines verlor mitten im Paddeln in 4 °C Wasser die Luft – ein Notauftauchen per Zodiac 800 Meter vom Schiff war nötig).',
            goal: 'Ausstattung von 4 Hurtigruten-Schiffen (MS Fram, MS Midnatsol, MS Trollfjord und MS Maud) mit 60 polartauglichen tragbaren SUP-Paketen, die unter arktischen Bedingungen von Zodiacs aus eingesetzt werden, den Temperaturbereich von -15 °C bis +10 °C und Eisbär-Begegnungsprotokolle bewältigen und die Luxus-Standards des Gästeerlebnisses wahren.',
