            background:
              'Die „Azure Collection“ betreibt 4 Luxus-Resorts auf den Malediven – Azure North (North-Malé-Atoll), Azure South (South-Malé-Atoll), Azure Private Island (Baa-Atoll) und Azure Retreat (Raa-Atoll). Die Gruppen-Wellness-Direktorin Simone Devereux, 39, eine ehemalige professionelle Yoga-Lehrerin aus Australien, war seit 7 Jahren bei Azure. 2022 befragte Simone 2.800 Gäste über alle 4 Häuser hinweg und stellte fest, dass 73 % Interesse an SUP-Yoga-Kursen äußerten, aber nur 12 % tatsächlich buchten – Haupthürde war der „Mangel an Sicherheit auf einem schmalen Board“ (von 64 % der Nichtbucher genannt). Die bestehende SUP-Flotte (3 Jahre alte Boards eines generischen chinesischen OEMs) umfasste insgesamt 14 Boards, geeignet für Flachwasser-Paddeln, aber zu instabil für Yoga – 32 Zoll breite Boards mit rutschigen EVA-Decks. Simone brauchte eine zweckgebaute SUP-Yoga-Flotte mit extra Breite, einer gepolsterten, rutschfesten Decks-Oberfläche für Barfuß-Yoga und der Fähigkeit, für Partner-Yoga-Asanas bis zu 350 lbs zu tragen.',
            goal: 'Einsatz einer Flotte von 40 spezialisierten SUP-Yoga-Boards über 4 Resorts, Entwicklung eines gestuften SUP-Yoga-Programms (Einsteiger, Fortgeschrittene, Könner, Partner) mit geschulten Trainern und Steigerung der SUP-Yoga-Buchungsconversion von 12 % auf 35 % innerhalb von 12 Monaten.',
