            location: 'Santa Monica, Kalifornien, Vereinigte Staaten',
            background:
              'Kai Yoshida, 36, ist seit 2014 professionelle Yoga-Lehrerin und seit 2017 zertifizierte SUP-Yoga-Trainerin. Über ihren Kanal „Calm Waters Yoga“ mit Strand-Yoga in Santa Monica, Venice Beach und Malibu baute sie 53.000 Instagram-Follower und 8.400 YouTube-Abonnenten auf. Seit 2019 bot sie Pop-up-SUP-Yoga-Kurse mit gemieteten Boards eines lokalen Verleihs an. 2022 unterrichtete sie 8-12 Kurse pro Monat mit 12-18 Schülern pro Kurs für 55 $ pro Schüler, aber die Mietvereinbarung brachte schwankende Board-Qualität (abgenutzte EVA-Pads, in 3 Fällen Ventilprobleme) und nur 38 % Nettomarge. Kai wollte ihre eigene Marke „Drift & Downward Dog“ launchen, mit einem Signature-Board-Design, das ihre kalifornische Strand-Ästhetik widerspiegelt, und auf über 20 Kurse pro Monat in der Santa Monica Bay ausbauen.',
            goal: 'Aufbau einer eigenen SUP-Yoga-Board-Marke mit 3 SKUs (ein Yoga-fokussiertes Allround-Board, ein Premium-extra-breites „Studio“-Board und ein kinderfreundliches Mini-SUP für Familienkurse), Launch einer DTC-Website mit Terminbuchungs-Plattform und 250.000 $ kombiniertem Produkt- und Kursumsatz im ersten Jahr.',
